gcG7(){return"\u062d\u062f\u0627\u06a9\u062b\u0631 \u06f5\u06f0\u06f0 \u0634\u0631\u062d \u067e\u0631\u062a\u06a9\u0631\u0627\u0631 \u0628\u0631\u0627\u06cc \u0647\u0645\u06cc\u0646 \u0628\u062e\u0634 \u0645\u062c\u0627\u0632 \u0627\u0633\u062a."},
gbpG(){return"\u0645\u0648\u0631\u062f\u06cc \u0628\u0627 \u0627\u06cc\u0646 \u062c\u0633\u062a\u200c\u0648\u062c\u0648 \u06cc\u0627\u0641\u062a \u0646\u0634\u062f."},
